use anyhow :: Context as _ ; use reqwest :: header :: HeaderMap ; use reqwest :: { Response , StatusCode , Url } ; # [doc = " Creates a HeaderMap from a vector of header key-value pairs"] pub fn create_headers (headers : Vec < (String , String) >) -> HeaderMap { let mut header_map = HeaderMap :: new () ; for (key , value) in headers { let header_name = reqwest :: header :: HeaderName :: from_bytes (key . as_bytes ()) . expect ("Invalid header name") ; let header_value = value . parse () . expect ("Invalid header value") ; header_map . insert (header_name , header_value) ; } header_map }